    }

    @Test
    void erro_regiaoInvalida() {
        CheckoutRequest req = new CheckoutRequest(
                camisetaMaisTenis(), "EXPRESSA", null, "PIX", 1, "BRONZE", "LESTE");
        assertEquals("REGIAO_INVALIDA", erroDe(req).getCodigo());
    }

    @Test
    void erro_modalidadeInvalida() {
